SELECT , ( SELECT COUNT(*) FROM organization_activity c WHERE (c.creator_user_id = a.creator_user_id OR c.brand_name = a.brand_name) AND c.is_deleted = 0 ) AS group_count FROM organization_activity a WHERE a.is_deleted = 0
AND a.status = #{status}
AND a.category = #{category}
AND a.tag_id = #{tagId}
AND ( a.title LIKE CONCAT('%', #{keyword}, '%') OR a.brand_name LIKE CONCAT('%', #{keyword}, '%') OR a.address LIKE CONCAT('%', #{keyword}, '%') OR a.category LIKE CONCAT('%', #{keyword}, '%') OR a.tag_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY a.create_time DESC

