mapper.update:
UPDATE organization_activity a
SET a.group_count = (
    SELECT COUNT(*)
    FROM (
        SELECT id
        FROM organization_activity c
        WHERE c.is_deleted = 0
          AND (

                c.creator_user_id = #{creatorUserId}


                OR


                c.brand_name = #{brandName}

          )
    ) matched
),
a.update_time = NOW()
WHERE a.is_deleted = 0
  AND (

        a.creator_user_id = #{creatorUserId}


        OR


        a.brand_name = #{brandName}

  )

UPDATE organization_activity_member
SET status = #{status},
    update_time = NOW()
WHERE activity_id = #{activityId}
  AND user_id = #{userId}

