SELECT , ( SELECT COUNT(*) FROM organization_activity c WHERE (c.creator_user_id = a.creator_user_id OR c.brand_name = a.brand_name) AND c.is_deleted = 0 ) AS group_count FROM organization_activity a WHERE a.is_deleted = 0 AND a.status = 'active' AND (
a.title LIKE CONCAT('%', #{kw}, '%') OR a.category LIKE CONCAT('%', #{kw}, '%') OR a.tag_name LIKE CONCAT('%', #{kw}, '%') OR a.address LIKE CONCAT('%', #{kw}, '%') OR a.host_desc LIKE CONCAT('%', #{kw}, '%')
) ORDER BY a.create_time DESC LIMIT #{limit}
